$new=$make($source,0);$check($runner->process_batch($new->id)['status']==='completed','real export creates requested new page');$newtarget=$repo->get($new->id)->items[0]['target_page_id'];$check(get_post_status($newtarget)==='draft'&&get_post_meta($newtarget,'_elementor_edit_mode',true)==='builder','new target remains editable draft');$check($runner->rollback($new->id)['status']==='rolled_back'&&get_post_status($newtarget)==='draft','new-page rollback retained');
